165	/**
166	 * Returns true if the user's 'Always Allow' selection for a specific tool
167	 * should trigger a session-wide transition to AUTO_EDIT mode.
168	 */
169	function isAutoEditTransition(
170	  tool: AnyDeclarativeTool,
171	  outcome: ToolConfirmationOutcome,
172	): boolean {
173	  // TODO: This is a temporary fix to enable AUTO_EDIT mode for specific
174	  // tools. We should refactor this so that callbacks can be removed from
175	  // tools.
176	  return (
177	    outcome === ToolConfirmationOutcome.ProceedAlways &&
178	    EDIT_TOOL_NAMES.has(tool.name)
179	  );
180	}
